func (s *APIPublicTestSuite) SetupSuite() {
	s.api = servertest.New(s.T(), "internal/behaviors/power/gen/api.yaml", gen.Routes)
}

func (s *APIPublicTestSuite) TestRoutes() {
	routes := gen.Routes(server.New(slog.Default(), nil, nil, dispatch.Deps{}))
	want := []struct {
		method     string
		path       string
		permission string
	}{
		{
			method:     http.MethodPost,
			path:       "/api/node/:hostname/power/reboot",
			permission: "power:execute",
		},
		{
			method:     http.MethodPost,
			path:       "/api/node/:hostname/power/shutdown",
			permission: "power:execute",
		},
	}

	s.Require().Len(routes, len(want))
	for i, w := range want {
		s.Run(w.method+" "+w.path, func() {
			s.Equal(w.method, routes[i].Method)
			s.Equal(w.path, routes[i].Path)
			s.Equal(w.permission, routes[i].Permission)
			s.NotNil(routes[i].Handler)
		})
	}
}

func TestAPIPublicTestSuite(
	t *testing.T,
) {
	suite.Run(t, new(APIPublicTestSuite))
}

